// Derived comparisons; source values and denominators remain inspectable.
async function initAnalysisInsights(){
 const ids=['cross-group-chart','task-gap-chart','perturbation-ranges','fixed-task-evidence','failure-depth-chart'];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const taskName=s=>s.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
 const number=n=>n.toFixed(2),signed=n=>(n>0?'+':'')+number(n);
 const astra='Astra (ICL)';let data;
 try{const r=await fetch('data/analysis-insights.json');if(!r.ok)throw Error('Analysis data');data=await r.json();}
 catch{for(const id of ids)document.getElementById(id).innerHTML='<p>Analysis data could not load. Please reload the page.</p>';return;}
 const label=id=>data.models.find(m=>m.id===id).label;
 const model=id=>esc(label(id));
 const groupRoot=document.getElementById('cross-group-chart');
 groupRoot.innerHTML=`<div class="insight-table-scroll"><table class="insight-table"><caption>Task-macro success rate (%) · best value in each row is bold</caption><thead><tr><th scope="col">Subgroup</th>${data.models.map(m=>`<th scope="col" ${m.id===astra?'class="insight-astra"':''}>${model(m.id)}</th>`).join('')}</tr></thead><tbody>${data.groups.map(g=>{const best=Math.max(...Object.values(g.rates));return `<tr><th scope="row"><button data-insight-group="${g.id}" aria-pressed="${g.id==='mobile-short'}">${esc(g.label)}<small>${g.n} tasks</small></button></th>${data.models.map(m=>`<td class="${m.id===astra?'insight-astra':''}">${Math.abs(g.rates[m.id]-best)<1e-8?'<strong>':''}${number(g.rates[m.id])}${Math.abs(g.rates[m.id]-best)<1e-8?'</strong>':''}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div><div class="insight-group-tasks" aria-live="polite"></div><p class="insight-note">Each task has equal weight. Mobility, horizon and precision are coupled in this suite; these are descriptive cross-groups. <a href="#study-limitations">Benchmark limitations ↗</a></p>`;
 function showGroup(id){const g=data.groups.find(g=>g.id===id);groupRoot.querySelector('.insight-group-tasks').innerHTML=`<strong>${esc(g.label)} · ${g.n} tasks</strong><p>${g.tasks.map(t=>esc(taskName(t))).join(' · ')}</p>`;groupRoot.querySelectorAll('[data-insight-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.insightGroup===id)));}
 groupRoot.addEventListener('click',e=>{const b=e.target.closest('[data-insight-group]');if(b)showGroup(b.dataset.insightGroup);});showGroup('mobile-short');

 const gaps=document.getElementById('task-gap-chart');
 gaps.innerHTML=`<div class="insight-controls"><label>Compare against<select id="gap-reference"><option value="best">Best other system, per task</option>${data.models.filter(m=>m.id!==astra).map(m=>`<option value="${esc(m.id)}">${model(m.id)}</option>`).join('')}</select></label><label>Task group<select id="gap-group"><option value="all">All 26 tasks</option>${data.groups.map(g=>`<option value="${g.id}">${esc(g.label)}</option>`).join('')}</select></label><label>Order<select id="gap-sort"><option value="gap">Largest advantage first</option><option value="task">Task name</option></select></label></div><p class="insight-note">GPT-6-Astra minus comparator · success-rate difference in percentage points. Select a row to see both scores.</p><div class="gap-axis"><span></span><div><span>−100 pp</span><span>0</span><span>+100 pp</span></div><span>Gap</span></div><div id="gap-rows"></div><p id="gap-readout" class="insight-readout" aria-live="polite">Select any task for the comparison.</p>`;
 let gapRows=[];
 function drawGaps(){
  const reference=gaps.querySelector('#gap-reference').value,group=gaps.querySelector('#gap-group').value,sort=gaps.querySelector('#gap-sort').value;
  const tasks=group==='all'?data.tasks:data.tasks.filter(t=>data.groups.find(g=>g.id===group).tasks.includes(t.task));
  gapRows=tasks.map(t=>{const competitors=data.models.filter(m=>m.id!==astra),best=reference==='best'?Math.max(...competitors.map(m=>t.rates[m.id])):t.rates[reference];return {...t,difference:t.rates[astra]-best,other:best,competitors:reference==='best'?competitors.filter(m=>Math.abs(t.rates[m.id]-best)<1e-8).map(m=>m.label).join(', '):label(reference)};}).sort((a,b)=>sort==='task'?a.task.localeCompare(b.task):b.difference-a.difference||a.task.localeCompare(b.task));
  gaps.querySelector('#gap-rows').innerHTML=gapRows.map(t=>`<button class="gap-row" data-gap-task="${t.task}" aria-label="${esc(taskName(t.task))}: GPT-6-Astra ${number(t.rates[astra])}%, ${esc(t.competitors)} ${number(t.other)}%, difference ${signed(t.difference)} percentage points"><span class="gap-task">${esc(taskName(t.task))}</span><span class="gap-track"><span class="gap-bar ${t.difference<0?'negative':'positive'}" style="left:${t.difference<0?50+t.difference/2:50}%;width:${Math.abs(t.difference)/2}%"></span>${Math.abs(t.difference)<1e-8?'<span class="gap-zero"></span>':''}</span><strong>${signed(t.difference)}</strong></button>`).join('');
  gaps.querySelector('#gap-readout').textContent=`${gapRows.length} tasks · ${reference==='best'?'comparator is the strongest other system on each task':label(reference)}. Select a row for its scores.`;
 }
 gaps.addEventListener('change',drawGaps);
 function inspectGap(e){const b=e.target.closest('[data-gap-task]');if(!b)return;const t=gapRows.find(t=>t.task===b.dataset.gapTask);gaps.querySelector('#gap-readout').textContent=`${taskName(t.task)}: GPT-6-Astra ${number(t.rates[astra])}% · ${t.competitors} ${number(t.other)}% · ${signed(t.difference)} pp. ${t.mobility}, ${t.horizon.toLowerCase()}, ${t.precision.toLowerCase()} precision.`;}
 gaps.addEventListener('click',inspectGap);gaps.addEventListener('focusin',inspectGap);drawGaps();

 const ranges=document.getElementById('perturbation-ranges');
 ranges.innerHTML=`<div class="perturbation-legend">${['Object','Background','Instruction','Mixed'].map((c,i)=>`<span><i class="condition-${i}"></i>${c}</span>`).join('')}</div><div class="range-axis"><span></span><div><span>0%</span><span>50%</span><span>100%</span></div><span>Range</span></div>${[...data.perturbations].sort((a,b)=>a.range-b.range).map(m=>{const min=Math.min(...m.conditions.map(c=>c.sr)),max=Math.max(...m.conditions.map(c=>c.sr));return `<div class="perturbation-row ${m.id===astra?'insight-astra':''}"><span>${esc(m.label)}</span><div class="perturbation-track"><span class="perturbation-span" style="left:${min}%;width:${max-min}%"></span>${m.conditions.map((c,i)=>`<button class="condition-dot condition-${i}" style="left:${c.sr}%;top:${6+i*10}px" data-condition-model="${esc(m.id)}" data-condition="${i}" aria-label="${esc(m.label)}, ${c.label}: ${number(c.sr)}%, ${c.episodes} episodes" title="${c.label}: ${number(c.sr)}%"></button>`).join('')}</div><strong>${number(m.range)} pp</strong></div>`;}).join('')}<p class="insight-readout" id="range-readout" aria-live="polite">Select a dot for its condition and sample size. Range = highest − lowest observed SR.</p>`;
 function inspectCondition(e){const b=e.target.closest('[data-condition-model]');if(!b)return;const m=data.perturbations.find(m=>m.id===b.dataset.conditionModel),c=m.conditions[Number(b.dataset.condition)];ranges.querySelector('#range-readout').textContent=`${m.label} · ${c.label}: ${number(c.sr)}% success across ${c.tasks} tasks / ${c.episodes} episodes.`;}
 ranges.addEventListener('click',inspectCondition);ranges.addEventListener('focusin',inspectCondition);

 const fixed=document.getElementById('fixed-task-evidence');
 fixed.innerHTML=`<div class="insight-table-scroll"><table class="insight-table fixed-insight-table"><caption>Fixed-base, low / medium precision · task success rate (%)</caption><thead><tr><th>Task</th><th>GPT-6-Astra</th><th>Qwen-RobotManip</th><th>Video</th></tr></thead><tbody>${data.groups.find(g=>g.id==='fixed-low-medium').tasks.map(name=>{const t=data.tasks.find(t=>t.task===name);return `<tr><th scope="row">${esc(taskName(name))}</th><td class="insight-astra">${number(t.rates[astra])}</td><td>${number(t.rates['Qwen-RobotManip'])}</td><td><button class="appendix-link" data-task-video="${name}">Video link ↗</button></td></tr>`;}).join('')}</tbody></table></div><p class="insight-note"><button class="appendix-link" data-open-case="fine">Glasses comparison ↗</button> · <button class="appendix-link" data-icl-package="frame_against_pen_holder">Frame demonstration ↗</button></p>`;

 const failures=document.getElementById('failure-depth-chart');
 const selected=['install_gear','utensils_to_holder','put_glass_in_glassbox','tighten_nut','peg_in_hole','shop','bottle'];
 failures.innerHTML='<div class="outcome-split-legend"><span><i class="outcome-success"></i>Complete success</span><span><i class="outcome-partial"></i>Incomplete · positive score</span><span><i class="outcome-zero"></i>Incomplete · zero score</span></div><div id="failure-depth-rows"></div><button class="failure-expand" type="button" aria-expanded="false" aria-controls="failure-depth-extra"><span data-failure-expand-label>Show all 26 tasks</span><span class="failure-expand-icon" aria-hidden="true">⌄</span></button><p class="insight-note">Percentages use all evaluated episodes within each task, including successes. Select a row for counts; scores reflect task-specific milestones.</p><p class="insight-readout" id="failure-readout" aria-live="polite">Select a task to inspect its outcome distribution.</p>';
 const initialRows=selected.map(name=>data.tasks.find(t=>t.task===name));
 const additionalRows=data.tasks.filter(t=>!selected.includes(t.task)).sort((a,b)=>b.zero/b.n-a.zero/a.n||a.task.localeCompare(b.task));
 const failureRow=t=>`<button class="failure-depth-row" data-failure-task="${t.task}" aria-label="${esc(taskName(t.task))}: ${t.success} successful, ${t.partial} incomplete with positive score, ${t.zero} zero score out of ${t.n}"><span>${esc(taskName(t.task))}</span><span class="outcome-split-track">${['success','partial','zero'].map(k=>`<span class="outcome-${k}" style="width:${100*t[k]/t.n}%">${100*t[k]/t.n>=10?Math.round(100*t[k]/t.n)+'%':''}</span>`).join('')}</span><span>${t.n} episodes</span></button>`;
 failures.querySelector('#failure-depth-rows').innerHTML=initialRows.map(failureRow).join('')+`<div id="failure-depth-extra" hidden>${additionalRows.map(failureRow).join('')}</div>`;
 const expandButton=failures.querySelector('.failure-expand');
 expandButton.addEventListener('click',()=>{
  const expanded=expandButton.getAttribute('aria-expanded')!=='true';
  expandButton.setAttribute('aria-expanded',String(expanded));
  failures.querySelector('#failure-depth-extra').hidden=!expanded;
  expandButton.querySelector('[data-failure-expand-label]').textContent=expanded?'Show fewer · 7 tasks':'Show all 26 tasks';
  if(!expanded){failures.querySelector('#failure-readout').textContent='Seven discussed tasks shown. Select a row to inspect its outcome distribution.';if(expandButton.getBoundingClientRect().top<90)expandButton.scrollIntoView({block:'center'});}
 });
 function inspectFailure(e){const b=e.target.closest('[data-failure-task]');if(!b)return;const t=data.tasks.find(t=>t.task===b.dataset.failureTask);failures.querySelector('#failure-readout').textContent=`${taskName(t.task)}: ${t.success}/${t.n} complete successes; ${t.partial}/${t.n} incomplete with positive score; ${t.zero}/${t.n} zero score (${number(t.zero/t.n*100)}%).`;}
 failures.addEventListener('click',inspectFailure);failures.addEventListener('focusin',inspectFailure);
}
